{
 "summary": "Accessible status needs a non-colour cue; the summary hides the failing runs.",
 "scores": [
  {
   "criterion": "Task clarity and hierarchy",
   "score": 3,
   "note": "Failures don't stand out."
  },
  {
   "criterion": "Accessibility",
   "score": 2,
   "note": "Muted text and colour-only status."
