 "issues": [
  {
   "id": "I1",
   "element": "Matrix cells (pass/fail)",
   "cell": "C3",
   "frame": "test-matrix",
   "problem": "Status is colour-only. Put a short marker back in each cell (check / x); it can shrink on narrow screens but shouldn't vanish.",
   "why": "A missed failure ships a broken release.",
   "fix": "Restore short text markers in the cells (a check for pass, an x for fail). Markers can shorten at narrow widths but must never disappear.",
   "severity": "high",
   "confidence": "high",
   "evidence": "Cells carry no text, icon or pattern; only fill colour changes."
  },
  {
   "id": "I2",
   "element": "Run summary \"27/31 passed\"",
   "cell": "G1",
   "frame": "test-matrix",
   "problem": "Pass-first summary hides failures. Lead with the failure count.",
   "why": "The summary is what people check before a release.",
   "fix": "Lead with failures: \"4 failed - 27 passed\", with the failure count in --danger #B42318.",
   "severity": "medium",
   "confidence": "high",
   "evidence": "Header reads \"27/31 passed\" while 4 red cells sit in the matrix."
  },
  {
   "id": "I3",
   "element": "Timestamps and subtitle (--text-muted)",
   "cell": "G3",
   "frame": "test-matrix",
   "problem": "Muted text #8B93A1 on the white page #FFFFFF is 3.09:1, under the 4.5:1 AA bar for 12-13px text.",
   "why": "The last-run times are how people judge whether a failure is current.",
   "fix": "--text-muted #8B93A1 -> #5F6673 (5.78:1 on #FFFFFF).",
   "severity": "high",
   "confidence": "high",
   "evidence": "Tokens: --text-muted #8B93A1, --page #FFFFFF; WCAG 2.2 ratio 3.09:1."
  }
 ],
 "answers": [
  {
   "question": "Can someone find today's failing suites in five seconds?",
   "answer": "No: colour alone and a pass-first summary hide them."
  },
  {
   "question": "Does the note band read as part of the page header?",
   "answer": "Mostly; it could use a little more separation."
  }
 ]
}
